@layer hj.components {
  /* Customise: --hj-autocomplete-height · --hj-autocomplete-radius · --hj-autocomplete-list-height */
  .hj-autocomplete-input,
  .hj-autocomplete-group {
    --_h: var(--hj-autocomplete-height, calc(48px * var(--hj-density-size)));
    --_ring: var(--hj-line);
    width: 100%;
    min-width: 0;
    height: var(--_h);
    border: 0;
    border-radius: var(--hj-autocomplete-radius, var(--hj-radius-pill));
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--_ring);
    color: var(--hj-fg);
    font: 500 15px / 1.2 var(--hj-font-sans);
    transition:
      box-shadow var(--hj-dur-fast) var(--hj-ease-out),
      background-color var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-autocomplete-input {
    padding: 0 calc(18px * var(--hj-density));
    outline: none;
    caret-color: var(--hj-accent);
  }
  .hj-autocomplete-input[data-size='sm'] {
    --_h: var(--hj-autocomplete-height, calc(40px * var(--hj-density-size)));
    font-size: 14px;
  }
  .hj-autocomplete-input[data-size='lg'] {
    --_h: var(--hj-autocomplete-height, calc(56px * var(--hj-density-size)));
    font-size: 16px;
  }
  .hj-autocomplete-input::placeholder {
    color: var(--hj-fg-mute);
    font-weight: 400;
    opacity: 1;
  }
  .hj-autocomplete-input::-webkit-search-cancel-button {
    display: none;
  }
  .hj-autocomplete-group {
    display: flex;
    align-items: center;
    gap: calc(8px * var(--hj-density));
    padding: 0 calc(8px * var(--hj-density)) 0 calc(16px * var(--hj-density));
    cursor: text;
  }
  .hj-autocomplete-group .hj-autocomplete-input {
    flex: 1;
    height: 100%;
    padding: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }
  .hj-autocomplete-input:hover:not([data-disabled]):not(:focus-visible),
  .hj-autocomplete-group:hover:not([data-disabled]):not(:focus-within) {
    --_ring: color-mix(in srgb, var(--hj-fg) 22%, transparent);
  }
  .hj-autocomplete-input:focus-visible,
  .hj-autocomplete-group:focus-within {
    --_ring: var(--hj-accent);
    box-shadow: inset 0 0 0 1.5px var(--_ring);
    outline: none;
  }
  .hj-autocomplete-group .hj-autocomplete-input:focus-visible {
    box-shadow: none;
  }
  .hj-autocomplete-group[data-disabled],
  .hj-autocomplete-input[data-disabled] {
    background: transparent;
    color: var(--hj-fg-mute);
    cursor: not-allowed;
  }

  .hj-autocomplete-icon {
    display: inline-flex;
    flex: none;
    font-size: 18px;
    line-height: 0;
    color: var(--hj-fg-mute);
    transition: color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-autocomplete-group:focus-within .hj-autocomplete-icon {
    color: var(--hj-accent-text);
  }
  .hj-autocomplete-icon svg,
  .hj-autocomplete-clear svg,
  .hj-autocomplete-trigger svg {
    width: 1em;
    height: 1em;
  }
  .hj-autocomplete-clear,
  .hj-autocomplete-trigger {
    position: relative;
    display: grid;
    place-items: center;
    flex: none;
    width: 30px;
    height: 30px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg-dim);
    font-size: 14px;
    line-height: 0;
    cursor: pointer;
    animation: hj-fade-in var(--hj-dur-fast) var(--hj-ease-out);
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-autocomplete-trigger {
    background: transparent;
    font-size: 18px;
  }
  .hj-autocomplete-clear::before,
  .hj-autocomplete-trigger::before {
    content: '';
    position: absolute;
    inset: -7px;
  }
  .hj-autocomplete-clear:hover,
  .hj-autocomplete-trigger:hover {
    background: color-mix(in srgb, var(--hj-fg) 10%, transparent);
    color: var(--hj-fg);
  }
  .hj-autocomplete-clear:active {
    transform: scale(0.9);
    transition-duration: 70ms;
  }

  .hj-autocomplete-positioner {
    z-index: var(--hj-z-popover);
    outline: none;
  }
  .hj-autocomplete-backdrop {
    position: fixed;
    inset: 0;
  }
  .hj-autocomplete-popup {
    box-sizing: border-box;
    width: var(--anchor-width);
    max-width: var(--available-width);
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-radius-md);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    background-clip: padding-box;
    box-shadow: var(--hj-shadow-lift);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    outline: none;
    transform-origin: var(--transform-origin);
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-autocomplete-popup[data-starting-style],
  .hj-autocomplete-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.97);
  }
  .hj-autocomplete-popup[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
  .hj-autocomplete-list {
    box-sizing: border-box;
    max-height: min(var(--hj-autocomplete-list-height, 360px), var(--available-height));
    padding: calc(6px * var(--hj-density));
    overflow-y: auto;
    overscroll-behavior: contain;
    outline: none;
  }
  .hj-autocomplete-list:empty {
    padding: 0;
  }
  .hj-autocomplete-item {
    display: flex;
    align-items: center;
    gap: calc(12px * var(--hj-density));
    min-height: calc(42px * var(--hj-density-size));
    padding: calc(6px * var(--hj-density)) calc(8px * var(--hj-density))
      calc(6px * var(--hj-density)) calc(12px * var(--hj-density));
    border-radius: var(--hj-radius-xs);
    corner-shape: var(--hj-corner-shape, round);
    font-size: 15px;
    line-height: 1.3;
    color: var(--hj-fg);
    cursor: default;
    user-select: none;
    outline: none;
    transition: background-color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-autocomplete-item > .hj-icon {
    color: var(--hj-fg-mute);
    font-size: 17px;
  }
  .hj-autocomplete-item[data-highlighted] {
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
  }
  .hj-autocomplete-item[data-disabled] {
    opacity: 0.4;
  }
  /* The typed part in bold ink, the remainder quieter: the eye lands on what's new. */
  .hj-autocomplete-highlight {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 500;
    color: var(--hj-fg-dim);
  }
  .hj-autocomplete-highlight mark {
    background: none;
    color: var(--hj-fg);
    font-weight: 700;
  }
  .hj-autocomplete-item-action {
    display: inline-flex;
    margin-left: auto;
    color: var(--hj-fg-mute);
  }

  .hj-autocomplete-empty:not(:empty) {
    padding: calc(22px * var(--hj-density)) calc(18px * var(--hj-density));
    font-size: 13.5px;
    line-height: 1.55;
    color: var(--hj-fg-mute);
  }
  .hj-autocomplete-empty b {
    color: var(--hj-fg);
    font-weight: 600;
  }
  .hj-autocomplete-status:not(:empty) {
    padding: calc(10px * var(--hj-density)) calc(14px * var(--hj-density)) 0;
    font-size: 12.5px;
    color: var(--hj-fg-mute);
  }
  .hj-autocomplete-group-label {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: calc(10px * var(--hj-density)) calc(8px * var(--hj-density))
      calc(4px * var(--hj-density)) calc(12px * var(--hj-density));
    font: var(--hj-type-eyebrow);
    letter-spacing: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
    color: var(--hj-fg-mute);
  }
  .hj-autocomplete-separator {
    height: 1px;
    margin: calc(6px * var(--hj-density)) calc(4px * var(--hj-density));
    background: var(--hj-line);
  }
  .hj-autocomplete-row {
    display: flex;
    gap: calc(4px * var(--hj-density));
  }
  .hj-autocomplete-arrow {
    width: 12px;
    height: 6px;
  }
}

'use client';
import { Autocomplete as Base } from '@base-ui/react/autocomplete';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

/** State owner: items, value (the input text), onValueChange, filter, mode. */
export const Root: typeof Base.Root = Base.Root;
export const Value: typeof Base.Value = Base.Value;
/** The field box holding a leading icon, the input, clear and trigger. */
export const InputGroup: HanjiPart<typeof Base.InputGroup> = part(
  Base.InputGroup,
  'Autocomplete.InputGroup',
  'hj-autocomplete-group',
);
export const List: HanjiPart<typeof Base.List> = part(
  Base.List,
  'Autocomplete.List',
  'hj-autocomplete-list',
);
export const Item: HanjiPart<typeof Base.Item> = part(
  Base.Item,
  'Autocomplete.Item',
  'hj-autocomplete-item',
);
export const Status: HanjiPart<typeof Base.Status> = part(
  Base.Status,
  'Autocomplete.Status',
  'hj-autocomplete-status',
);
export const Empty: HanjiPart<typeof Base.Empty> = part(
  Base.Empty,
  'Autocomplete.Empty',
  'hj-autocomplete-empty',
);
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'Autocomplete.Backdrop',
  'hj-autocomplete-backdrop',
);
export const Popup: HanjiPart<typeof Base.Popup> = part(
  Base.Popup,
  'Autocomplete.Popup',
  'hj-autocomplete-popup',
);
export const Arrow: HanjiPart<typeof Base.Arrow> = part(
  Base.Arrow,
  'Autocomplete.Arrow',
  'hj-autocomplete-arrow',
);
export const Group: HanjiPart<typeof Base.Group> = part(
  Base.Group,
  'Autocomplete.Group',
  'hj-autocomplete-group-items',
);
export const GroupLabel: HanjiPart<typeof Base.GroupLabel> = part(
  Base.GroupLabel,
  'Autocomplete.GroupLabel',
  'hj-autocomplete-group-label',
);
export const Separator: HanjiPart<typeof Base.Separator> = part(
  Base.Separator,
  'Autocomplete.Separator',
  'hj-autocomplete-separator',
);
export const Row: HanjiPart<typeof Base.Row> = part(
  Base.Row,
  'Autocomplete.Row',
  'hj-autocomplete-row',
);
export const Collection: typeof Base.Collection = Base.Collection;
export const useFilter: typeof Base.useFilter = Base.useFilter;
export const useFilteredItems: typeof Base.useFilteredItems = Base.useFilteredItems;
/** A trailing action inside a suggestion (e.g. remove a recent search). */
export const ItemAction: (props: ElementPartProps<'span'>) => React.ReactElement = elementPart(
  'span',
  'Autocomplete.ItemAction',
  'hj-autocomplete-item-action',
);

/** Portals to `<body>` but keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

export interface InputOwnProps {
  /** Heights 40 / 48 / 56 when the input draws its own box (outside an InputGroup). */
  size?: 'sm' | 'md' | 'lg';
}
export interface InputProps extends InputOwnProps, Omit<Base.Input.Props, 'size'> {}

/** The search input. Alone it draws a field box; inside InputGroup it is bare text. */
export function Input(props: InputProps): React.ReactElement {
  const config = useHanjiConfig();
  const { size = 'md', className, ...rest } = withDefaults(config, 'Autocomplete.Input', props);
  return (
    <Base.Input
      {...rest}
      data-size={size}
      className={cls(config, 'Autocomplete.Input', 'hj-autocomplete-input', className)}
    />
  );
}

/** Leading glyph inside the InputGroup. Defaults to the adapter's search icon. */
export function Icon({ children, className, ...props }: Base.Icon.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.Icon
      {...props}
      className={cls(config, 'Autocomplete.Icon', 'hj-autocomplete-icon', className)}
    >
      {children ?? config.icons.search}
    </Base.Icon>
  );
}

/** Clears the input. Defaults to ✕ with the localised “Clear” label. */
export function Clear({ children, className, ...props }: Base.Clear.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.Clear
      aria-label={config.strings.clear}
      {...props}
      className={cls(config, 'Autocomplete.Clear', 'hj-autocomplete-clear', className)}
    >
      {children ?? config.icons.x}
    </Base.Clear>
  );
}

/** Opens the suggestions. Defaults to the adapter's chevron. */
export function Trigger({ children, className, ...props }: Base.Trigger.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.Trigger
      {...props}
      className={cls(config, 'Autocomplete.Trigger', 'hj-autocomplete-trigger', className)}
    >
      {children ?? config.icons.chevronDown}
    </Base.Trigger>
  );
}

/** Places the popup under the field, gap 6. */
export function Positioner({
  sideOffset = 6,
  collisionPadding = 8,
  className,
  ...props
}: Base.Positioner.Props): React.ReactElement {
  const config = useHanjiConfig();
  return (
    <Base.Positioner
      {...props}
      sideOffset={sideOffset}
      collisionPadding={collisionPadding}
      className={cls(config, 'Autocomplete.Positioner', 'hj-autocomplete-positioner', className)}
    />
  );
}

export interface HighlightOwnProps {
  /** The suggestion text. */
  text: string;
  /** What the user typed. Every case-insensitive match is set in bold. */
  query: string;
}
export interface HighlightProps
  extends HighlightOwnProps, Omit<React.ComponentProps<'span'>, 'children'> {}

const escape = (s: string): string => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Sets the typed part of a suggestion in bold, the rest quieter — the eye finds the difference. */
export function Highlight({
  text,
  query,
  className,
  ...props
}: HighlightProps): React.ReactElement {
  const config = useHanjiConfig();
  const q = query.trim();
  const parts = q ? text.split(new RegExp(`(${escape(q)})`, 'gi')) : [text];
  const lower = q.toLowerCase();
  return (
    <span
      {...props}
      className={
        cls(config, 'Autocomplete.Highlight', 'hj-autocomplete-highlight', className) as string
      }
    >
      {parts.map((p, i) =>
        q && p.toLowerCase() === lower ? (
          // oxlint-disable-next-line react/no-array-index-key -- split segments have no identity
          <mark key={i}>{p}</mark>
        ) : (
          // oxlint-disable-next-line react/no-array-index-key
          <React.Fragment key={i}>{p}</React.Fragment>
        ),
      )}
    </span>
  );
}

export interface ContentOwnProps {
  /** Shown when nothing matches: say what was searched and what to try. */
  empty?: React.ReactNode;
  side?: Base.Positioner.Props['side'];
  align?: Base.Positioner.Props['align'];
  container?: Base.Portal.Props['container'];
  /** The list's children: nodes, or a render function per filtered item. */
  children?: Base.List.Props['children'];
}
export interface ContentProps extends ContentOwnProps, Omit<Base.Popup.Props, 'children'> {}

/** Shorthand for Portal + Positioner + Popup + Empty + List. */
export function Content({
  empty,
  side,
  align,
  container,
  children,
  ...popup
}: ContentProps): React.ReactElement {
  return (
    <Portal container={container}>
      <Positioner side={side} align={align}>
        <Popup {...popup}>
          {empty ? <Empty>{empty}</Empty> : null}
          <List>{children}</List>
        </Popup>
      </Positioner>
    </Portal>
  );
}

export * as Autocomplete from './autocomplete.tsx';
export type {
  ContentProps as AutocompleteContentProps,
  HighlightProps as AutocompleteHighlightProps,
  InputProps as AutocompleteInputProps,
} from './autocomplete.tsx';
